import {brandLogo} from '../shared/brand.js?v=5.1.0';
import {CLOUD} from '../shared/cloud-config.js?v=5.1.0';
import {UI} from '../shared/copy.js?v=5.1.0';import {CHAT_COPY} from '../shared/conversation-copy.js?v=5.1.0';import {esc,getLang} from '../shared/core.js?v=5.1.0';import {SAMPLE_STORAGE} from '../shared/owner-sample.js?v=5.1.0';import {readState,configureState} from '../shared/state.js?v=5.1.0';import {publicStore} from '../shared/cloud.js?v=5.1.0';
const params=new URLSearchParams(location.search),lang=getLang(),t={...UI[lang],...CHAT_COPY[lang]},table=Math.min(999,Math.max(1,parseInt(params.get('table'),10)||3)),store=params.get('store'),preview=params.get('preview')==='1';if(preview&&params.get('sample')==='owner')configureState(SAMPLE_STORAGE);document.documentElement.lang=lang;document.querySelector('#controls').innerHTML=`<button class="primary" id="print">${esc(t.printQr)}</button><a class="secondary" href="owner.html?lang=${lang}${store?'&store='+encodeURIComponent(store):''}">${esc(t.back)}</a>`;
try{const data=store?await publicStore(store):preview?{store:readState().store}:null;if(!data)throw Error('storeMissing');const url=new URL(`./?lang=${lang}&table=${table}${store?'&store='+encodeURIComponent(store):'&preview=1'+(params.get('sample')==='owner'?'&sample=owner':'')}`,preview?location.href:CLOUD.guestBase).href;const code=qrcode(0,'M');code.addData(url);code.make();document.querySelector('#paper').innerHTML=`<h3>${esc(data.store.name)}</h3><p>${esc(t.table)} ${String(table).padStart(2,'0')}</p><div class="qr-code">${code.createSvgTag({cellSize:5,margin:4,scalable:true})}</div><p>${esc(t.menu)} · ${esc(t.chat)}</p><p>${esc(t.chooseLanguage)}</p><small>${esc(t.qrNote)}</small><small>${esc(t.noRealPayment)}</small><div class="print-brand">${brandLogo()}</div>`;document.querySelector('#print').addEventListener('click',()=>window.print());}catch(e){document.querySelector('#paper').textContent=t[e.message]||t.cloudError;document.querySelector('#print').disabled=true;}
